function switchTab(e){document.querySelectorAll(".sub-nav-item").forEach(t=>{t.classList.toggle("active",t.getAttribute("data-tab")===e)}),document.querySelectorAll(".tab-content").forEach(t=>{t.style.display=t.id===`tab-${e}`?"block":"none"}),window.scrollTo({top:document.querySelector(".subject-nav").offsetTop-80,behavior:"smooth"}),window.MathJax&&window.MathJax.typesetPromise&&window.MathJax.typesetPromise()}function bindTabs(){document.querySelectorAll(".sub-nav-item").forEach(e=>{e.addEventListener("click",()=>switchTab(e.getAttribute("data-tab")))})}document.readyState==="loading"?document.addEventListener("DOMContentLoaded",bindTabs):bindTabs();
